// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != newOwner);
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        address currentOwner = c.owner();
        bool changed = (currentOwner == newOwner && currentOwner != c.owner());
        assertTrue((caller == c.owner() && changed) || (caller != c.owner() && !changed));
    }
}
